$address = $record['address'] ?? null;
$coverage = $record['coverage'] ?? null;
$rv = function ($postKey, $object, $property = null, $default = '') use ($data) {
    if (array_key_exists($postKey, $data)) return (string)$data[$postKey];
    $property = $property ?: $postKey;
    return is_object($object) && isset($object->$property) ? (string)$object->$property : $default;
};
