<script>
(function(){var insurer=document.getElementById('health_insurer_id'),plan=document.getElementById('health_plan_id');if(!insurer||!plan)return;function filter(){Array.from(plan.options).forEach(function(o){if(!o.dataset.insurer)return;o.hidden=insurer.value!=='0'&&o.dataset.insurer!==insurer.value;});if(plan.selectedOptions[0]&&plan.selectedOptions[0].hidden)plan.value='0';}insurer.addEventListener('change',filter);filter();})();
</script>
